{"command": "/root/.venv/bin/python - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('/root/test-supply.xlsx')
# Replace formulas manually
for wsname in ['CFC data','Production']:
 ws=wb[wsname]
 for row in ws.iter_rows():
  for c in row:
   v=c.value
   if isinstance(v,str) and 'XLOOKUP' in v:
    if 'PWT' in v:
      year_ref=v.split('(')[1].split(',')[0]
      c.value=f'=INDEX(PWT!$B$2:$B$35,MATCH({year_ref},PWT!$A$2:$A$35,0))'
    elif 'WEO_Data' in v:
      year_ref=v.split('(')[1].split(',')[0]
      c.value=f'=INDEX(WEO_Data!$C$8:$C$51,MATCH({year_ref},WEO_Data!$B$8:$B$51,0))'
# Fix B3 simpler
wb['Production']['B3']='=AVERAGE(E22:E29)'
# Future KY constant explicit
for r in range(58,76):
 wb['Production'][f'D{r}']='=AVERAGE($D$49:$D$57)'
wb.save('/root/test-supply.xlsx')
PY", "security_risk": "MEDIUM", "summary": "Replace unsupported XLOOKUP formulas with INDEX MATCH", "timeout": 60}

